import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position, rotation, scale
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ, scaleXYZ } = config.scenePosition;
    group.position.set(x, y, z);

    if (rotationXYZ) {
      group.rotation.set(rotationXYZ[0], rotationXYZ[1], rotationXYZ[2]);
    }

    if (scaleXYZ) {
      group.scale.set(scaleXYZ[0], scaleXYZ[1], scaleXYZ[2]);
    }
  }

  // Create card plane with feature image texture
  const cardGeom = new THREE.PlaneGeometry(1, 0.625); // 512:320 aspect ratio
  const cardTexture = ctx.textureLoader.load(config.imageUrl || '/prism-mock/home/nodes/feature-card.png');

  const cardMaterial = new THREE.MeshBasicNodeMaterial({
    map: cardTexture,
    transparent: true,
    side: THREE.FrontSide,
  });

  const cardMesh = new THREE.Mesh(cardGeom, cardMaterial);
  group.add(cardMesh);

  // Render text label via fontAtlas
  if (config.textContent?.length) {
    const textStr = config.textContent[0];

    const textMesh = ctx.fontAtlas.createTextMesh(textStr, {
      fontSize: 0.34,
      fontName: 'Lora',
      fontWeight: 400,
      align: 'left',
      anchorX: 'left',
      anchorY: 'top',
      color: 0xe8ecf2,
    });

    if (textMesh) {
      textMesh.position.set(-0.45, 0.25, 0.01);
      group.add(textMesh);
    }
  }

  // Apply cinematic primitives if configured
  if (config.cinematicPrimitives?.length && ctx.primitives) {
    for (const prim of config.cinematicPrimitives) {
      const applyPrim = ctx.primitives[prim.name];
      if (typeof applyPrim === 'function') {
        applyPrim(group, prim.params || {});
      }
    }
  }

  // Setup resource cleanup
  group.userData.cleanup = () => {
    cardGeom.dispose();
    cardMaterial.dispose();
    cardTexture.dispose();

    gsap.killTweensOf(group);

    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach(m => m?.dispose?.());
      }
    });
  };

  // Event handlers
  group.userData.handlers = {};

  return group;
}
